SELECT COUNT(*) FROM (
    SELECT DISTINCT asd.prim_dx, asd.sec_dx 
    FROM assessmentsocialanddiagnosis asd
) sub;

SELECT COUNT(DISTINCT c.clin_key) FROM clinicians c
JOIN treatmentbasics tb ON tb.enc_ref IN (SELECT enc_key FROM encounters WHERE clin_id = c.clin_key)
WHERE tb.tx_key IS NOT NULL;
